def fail(message: str, code: int = 1) -> "NoReturn":
    print(f"\n[Pharma-Khaato] {message}", file=sys.stderr)
    if platform.system() == "Windows" and sys.stdin.isatty():
        try:
            input("Press Enter to close...")
        except EOFError:
            pass
    raise SystemExit(code)


def cache_root() -> Path:
    system = platform.system()
    if system == "Windows":
        base = Path(os.environ.get("LOCALAPPDATA") or Path.home())
        return base / "PharmaKhaato-Test"
    xdg_cache = os.environ.get("XDG_CACHE_HOME")
    return (Path(xdg_cache) if xdg_cache else Path.home() / ".cache") / "pharma-khaato-test"


def decode_payload() -> bytes:
    compact = "".join(PAYLOAD_B85.split())
    data = base64.b85decode(compact.encode("ascii"))
    actual = hashlib.sha256(data).hexdigest()
    if actual != PAYLOAD_SHA256:
        fail("Embedded application payload failed checksum verification.")
    return data


def safe_extract(data: bytes, destination: Path) -> None:
    destination.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(data)) as zf:
        root = destination.resolve()
        for info in zf.infolist():
            target = (destination / info.filename).resolve()
            if root != target and root not in target.parents:
                fail("Unsafe path detected in embedded application payload.")
        zf.extractall(destination)


def ensure_app(root: Path) -> Path:
    version_root = root / APP_VERSION
    app_dir = version_root / "app"
    marker = version_root / "payload.sha256"
    current = marker.read_text(encoding="utf-8").strip() if marker.exists() else ""
    if current != PAYLOAD_SHA256 or not (app_dir / "main.py").exists():
        if app_dir.exists():
            shutil.rmtree(app_dir, ignore_errors=True)
        app_dir.mkdir(parents=True, exist_ok=True)
        print("[Pharma-Khaato] Preparing bundled application...")
        safe_extract(decode_payload(), app_dir)
        marker.parent.mkdir(parents=True, exist_ok=True)
        marker.write_text(PAYLOAD_SHA256, encoding="utf-8")
    return app_dir


def venv_python(env_dir: Path) -> Path:
    if platform.system() == "Windows":
        return env_dir / "Scripts" / "python.exe"
    return env_dir / "bin" / "python"


def ensure_runtime(version_root: Path, app_dir: Path, reinstall: bool) -> Path:
    env_dir = version_root / "venv"
    py = venv_python(env_dir)
    if reinstall and env_dir.exists():
        print("[Pharma-Khaato] Rebuilding isolated runtime...")
        shutil.rmtree(env_dir, ignore_errors=True)
    if not py.exists():
        print("[Pharma-Khaato] Creating isolated Python environment...")
        try:
            venv.EnvBuilder(with_pip=True, clear=False).create(env_dir)
        except Exception as exc:
            hint = " On Debian/Ubuntu, install the python3-venv package." if platform.system() == "Linux" else ""
            fail(f"Could not create the virtual environment: {exc}.{hint}")
        py = venv_python(env_dir)

    probe = subprocess.run(
        [str(py), "-c", "import PySide6, dotenv; print(PySide6.__version__)"],
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        text=True,
    )
    if probe.returncode != 0:
        print("[Pharma-Khaato] Installing PySide6 runtime (first launch needs internet)...")
        cmd = [str(py), "-m", "pip", "install", "--disable-pip-version-check", "-r", str(app_dir / "requirements.txt")]
        try:
            subprocess.run(cmd, check=True)
        except subprocess.CalledProcessError:
            fail("Runtime installation failed. Check your internet connection and Python/pip installation.")
    else:
        print(f"[Pharma-Khaato] Runtime ready (PySide6 {probe.stdout.strip()}).")
    return py


def main() -> int:
    if platform.system() not in {"Windows", "Linux"}:
        fail("This test launcher supports Windows and Linux.")
    if sys.version_info < (3, 10):
        fail(f"Python 3.10+ is required; this launcher is running on {sys.version.split()[0]}.")

    reset_data = "--reset-data" in sys.argv[1:]
    reinstall = "--reinstall-runtime" in sys.argv[1:]
    forwarded = [arg for arg in sys.argv[1:] if arg not in {"--reset-data", "--reinstall-runtime"}]

    root = cache_root()
    version_root = root / APP_VERSION
    app_dir = ensure_app(root)
    data_dir = version_root / "user-data"
    if reset_data and data_dir.exists():
        print("[Pharma-Khaato] Resetting isolated test data...")
        shutil.rmtree(data_dir, ignore_errors=True)
    data_dir.mkdir(parents=True, exist_ok=True)

    py = ensure_runtime(version_root, app_dir, reinstall)
    env = os.environ.copy()
    env["PHARMA_KHAATO_DATA_DIR"] = str(data_dir)
    env["PYTHONUNBUFFERED"] = "1"

    print("[Pharma-Khaato] Launching v2.3.1 UI...")
    print(f"[Pharma-Khaato] Test data: {data_dir}")
    try:
        completed = subprocess.run([str(py), str(app_dir / "main.py"), *forwarded], cwd=app_dir, env=env)
    except KeyboardInterrupt:
        return 130
    except OSError as exc:
        fail(f"Could not start the application: {exc}")
    if completed.returncode != 0:
        print("\n[Pharma-Khaato] The GUI exited with an error.", file=sys.stderr)
        if platform.system() == "Linux":
            print("If Qt reports an xcb/Wayland library error, install the missing desktop Qt/XCB system package for your distribution.", file=sys.stderr)
    return completed.returncode


if __name__ == "__main__":
    raise SystemExit(main())
